style.css:
@-moz-document domain("google.com"), domain("google.kz") {
/* Colors */
    :root {
        --my-blue: #174f83;
        --my-deep-blue: #102f50;
        --my-glass: rgba(16, 52, 79, 0.88);
        --my-green: #8ccf65;
        --my-text: #e5f5f5;
    }

    /* Background */
    body {
        background:
            radial-gradient(
                ellipse at 50% 0%,
                #397eb0 0%,
                transparent 65%
            ),
            linear-gradient(
                145deg,
                #102f50,
                #174f65 55%,
                #183e36
            ) !important;
        background-attachment: fixed !important;
        color: var(--my-text) !important;
    }

    /* Search box */
    textarea[name="q"],
    input[name="q"] {
        background: rgba(15, 48, 73, 0.88) !important;
        color: #eafaff !important;
        border: 1px solid rgba(160, 220, 230, 0.45) !important;
        border-radius: 28px !important;
        box-shadow:
            inset 0 2px 8px rgba(0, 0, 0, 0.25),
            0 4px 16px rgba(0, 0, 0, 0.18) !important;
    }

    /* Search buttons */
    input[type="submit"],
    button {
        background: linear-gradient(
            180deg,
            #5598b5,
            #245c7b
        ) !important;
        color: #efffff !important;
        border: 1px solid rgba(190, 240, 255, 0.4) !important;
        border-radius: 18px !important;
        box-shadow: 0 3px 10px rgba(0, 0, 0, 0.25) !important;
    }

    /* Links */
    a {
        color: #91d9b0 !important;
    }

    /* Images */
    img {
        border-radius: 8px !important;
    }
}
